-- Catalog-only: no default in ADD COLUMN, so no table rewrite and no scan.
-- The default is set in the same transaction, so every row inserted after this commit gets a value.
SET LOCAL lock_timeout = '5s';
ALTER TABLE orders ADD COLUMN public_id uuid;
ALTER TABLE orders ALTER COLUMN public_id SET DEFAULT gen_random_uuid();

Write /home/dev/project/migrations/0005_orders_public_id_backfill.sql
-- migrate:no-transaction
-- 0003 sets lock_timeout at session level, and this runner reuses one connection, so clear it here.
RESET lock_timeout;

-- Fills existing rows in keyset batches. Each batch is its own transaction, so row locks are held
-- only for one batch and ROW EXCLUSIVE on the table is never held across batches. Rows that get
-- inserted or updated during the backfill already have public_id from the column default.
-- Re-running is safe: only rows still NULL are touched.
DO $$
DECLARE
  chunk constant bigint := 5000;
  lower_key bigint := 0;
  upper_bound bigint;
BEGIN
  SELECT coalesce(max(id), 0) INTO upper_bound FROM orders;
  WHILE lower_key <= upper_bound LOOP
    UPDATE orders
       SET public_id = gen_random_uuid()
     WHERE id >= lower_key AND id < lower_key + chunk
       AND public_id IS NULL;
    lower_key := lower_key + chunk;
    COMMIT;
  END LOOP;
END
$$;

Write /home/dev/project/migrations/0006_orders_public_id_index.sql
-- migrate:no-transaction
-- CONCURRENTLY: builds under SHARE UPDATE EXCLUSIVE, so reads and writes on orders continue.
-- No lock_timeout here: a concurrent build that times out leaves an INVALID index behind.
-- Clear the session lock_timeout inherited from 0003.
RESET lock_timeout;

-- A failed build leaves an INVALID index that IF NOT EXISTS would keep. Drop it, then rebuild.
DROP INDEX CONCURRENTLY IF EXISTS orders_public_id_key;
CREATE UNIQUE INDEX CONCURRENTLY orders_public_id_key ON orders (public_id);

