-- Promotes the existing unique index to a constraint. Catalog-only, so no scan.
SET LOCAL lock_timeout = '5s';
ALTER TABLE orders ADD CONSTRAINT orders_public_id_key UNIQUE USING INDEX orders_public_id_key;

