-- PostgreSQL 18: NOT VALID not-null is catalog-only. attnotnull is set immediately, so codegen
-- sees NOT NULL, and new rows are enforced. Existing rows are checked by 0009.
SET LOCAL lock_timeout = '5s';
ALTER TABLE orders ADD CONSTRAINT orders_public_id_not_null NOT NULL public_id NOT VALID;

