-- Scans orders under SHARE UPDATE EXCLUSIVE: reads and writes continue. Separate file, so a
-- separate transaction from 0008 (the runner commits per file).
SET LOCAL lock_timeout = '5s';
ALTER TABLE orders VALIDATE CONSTRAINT orders_public_id_not_null;

